const repo = 'octocat/Hello-World'; // CHANGE THIS
const language = 'EN'; // EN or FR
const slackWebhook = 'https://example.invalid/slack-webhook'; // CHANGE THIS
const githubToken = ''; // Optional for public repos
const anthropicKey = ''; // CHANGE THIS; never commit real keys
if (!/^[\w.-]+\/[\w.-]+$/.test(repo)) throw Error('Invalid owner/repo');
if (!['EN','FR'].includes(language)) throw Error('Language must be EN or FR');
if (!anthropicKey || slackWebhook.includes('example.invalid')) throw Error('Configure credentials before executing');
return [{json:{repo,language,slackWebhook,githubToken,anthropicKey,since:new Date(Date.now()-7*86400000).toISOString()}}];

const c = $('Configuration').first().json;
const headers = {'Accept':'application/vnd.github+json','User-Agent':'weekly-dev-summary'};
if (c.githubToken) headers.Authorization = 'Bearer ' + c.githubToken;
async function pages(endpoint, params) {
  const all=[];
  for(let page=1;page<=20;page++) {
    const query=new URLSearchParams({...params,per_page:'100',page:String(page)}).toString();
    const data=await this.helpers.httpRequest({method:'GET',url:'https://api.github.com/repos/'+c.repo+'/'+endpoint+'?'+query,headers,json:true});
    if(!Array.isArray(data))throw Error('Unexpected GitHub API response');
    all.push(...data);
    if(data.length<100)return all;
  }
  throw Error('GitHub result exceeded 20 pages; narrow time window');
}
const [commits,issues,pulls]=await Promise.all([
  pages.call(this,'commits',{since:c.since}),
  pages.call(this,'issues',{state:'closed',since:c.since}),
  pages.call(this,'pulls',{state:'closed',sort:'updated',direction:'desc'})
]);
return [{json:{...c,
  commits:commits.map(x=>({sha:x.sha.slice(0,7),message:x.commit.message.split('\n')[0]})),
  issues:issues.filter(x=>!x.pull_request&&x.closed_at>=c.since).map(x=>({number:x.number,title:x.title})),
  pulls:pulls.filter(x=>x.merged_at&&x.merged_at>=c.since).map(x=>({number:x.number,title:x.title}))
}}];

const d=$input.first().json;
const prompt=`Write a factual weekly development summary for ${d.repo} in ${d.language==='FR'?'French':'English'}. Include commits, closed issues, merged pull requests, and key highlights. Do not invent details. Data: ${JSON.stringify({commits:d.commits,issues:d.issues,pulls:d.pulls})}`;
const result=await this.helpers.httpRequest({method:'POST',url:'https://api.anthropic.com/v1/messages',headers:{'x-api-key':d.anthropicKey,'anthropic-version':'2023-06-01','content-type':'application/json'},body:{model:'claude-sonnet-4-5',max_tokens:1200,messages:[{role:'user',content:prompt}]},json:true});
const text=result.content.filter(x=>x.type==='text').map(x=>x.text).join('\n');
if(!text)throw Error('Empty Claude response');
return [{json:{slackWebhook:d.slackWebhook,text}}];
